"""Fixed replay corpora: canonical request files plus a checksummed manifest.

A corpus is a directory holding ``requests.jsonl`` (one canonical-JSON
``GenerationRequest`` per line) and ``corpus.json`` (identity, provenance, file
digests and, for offline providers, the expected plan digest). Everything a
comparison depends on is therefore pinned by bytes, not by a description.

Two kinds exist and are never mixed inside one run:

* ``replay``: committed, generated by a documented deterministic command.
* ``live``: recorded from real play, git-ignored, not reproducible from the repo.
"""

from __future__ import annotations

import hashlib
import json
import re
from collections import Counter
from pathlib import Path
from typing import Any

from dungeon_director.contracts import CONTRACT_VERSION, GenerationRequest

CORPUS_SCHEMA_VERSION = "1.0.0"
MANIFEST_NAME = "corpus.json"
REQUESTS_NAME = "requests.jsonl"
CORPUS_KINDS = ("replay", "live")
_PLAIN_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")


class CorpusError(ValueError):
    """The corpus is missing, malformed, or does not match its manifest."""


def canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    return sha256_bytes(path.read_bytes())


class Corpus:
    """A verified corpus: manifest plus parsed requests, in file order."""

    def __init__(self, manifest_path: Path, manifest: dict[str, Any], requests: list[Any]) -> None:
        self.manifest_path = manifest_path
        self.manifest = manifest
        self.requests: list[GenerationRequest] = requests

    @property
    def corpus_id(self) -> str:
        return str(self.manifest["corpus_id"])

    @property
    def kind(self) -> str:
        return str(self.manifest["kind"])

    @property
    def requests_sha256(self) -> str:
        return str(self.manifest["files"][0]["sha256"])

    def identity(self) -> dict[str, Any]:
        return {
            "corpus_id": self.corpus_id,
            "kind": self.kind,
            "records": len(self.requests),
            "requests_sha256": self.requests_sha256,
            "manifest_sha256": sha256_file(self.manifest_path),
        }


def _read_manifest(manifest_path: Path) -> dict[str, Any]:
    if not manifest_path.is_file():
        raise CorpusError(f"corpus manifest not found: {manifest_path}")
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise CorpusError(f"{manifest_path}: unreadable manifest: {exc}") from exc
    if not isinstance(manifest, dict):
        raise CorpusError(f"{manifest_path}: manifest must be a JSON object")
    return manifest


def verify_corpus(manifest_path: str | Path) -> tuple[list[str], list[GenerationRequest]]:
    """Check a corpus against its manifest; return (problems, parsed requests)."""
    path = Path(manifest_path)
    manifest = _read_manifest(path)
    problems: list[str] = []
    requests: list[GenerationRequest] = []

    for key in ("schema_version", "corpus_id", "kind", "contract_version", "files", "provenance"):
        if key not in manifest:
            problems.append(f"manifest is missing {key!r}")
    if problems:
        return problems, requests
    if str(manifest["schema_version"]).split(".")[0] != CORPUS_SCHEMA_VERSION.split(".")[0]:
        problems.append(f"unsupported corpus schema_version {manifest['schema_version']!r}")
    if manifest["kind"] not in CORPUS_KINDS:
        problems.append(f"kind must be one of {CORPUS_KINDS}, got {manifest['kind']!r}")
    if str(manifest["contract_version"]).split(".")[0] != CONTRACT_VERSION.split(".")[0]:
        problems.append(
            f"corpus contract_version {manifest['contract_version']!r} is incompatible "
            f"with the director contract {CONTRACT_VERSION!r}"
        )
    files = manifest["files"]
    if (
        not isinstance(files, list)
        or len(files) != 1
        or not isinstance(files[0], dict)
        or files[0].get("path") != REQUESTS_NAME
    ):
        problems.append(f"files must list exactly one entry, {REQUESTS_NAME!r}")
        return problems, requests

    entry = files[0]
    name = entry["path"]
    if not _PLAIN_NAME_RE.match(name):
        problems.append(f"file name {name!r} must be a plain file name")
        return problems, requests
    data_path = path.parent / name
    if not data_path.is_file():
        problems.append(f"{name}: file not found next to the manifest")
        return problems, requests

    raw = data_path.read_bytes()
    if sha256_bytes(raw) != entry.get("sha256"):
        problems.append(f"{name}: sha256 does not match the manifest (file changed?)")
    if len(raw) != entry.get("bytes"):
        problems.append(f"{name}: size {len(raw)} does not match the manifest {entry.get('bytes')}")
    text = raw.decode("utf-8", errors="replace")
    if text and not text.endswith("\n"):
        problems.append(f"{name}: must end with a newline")

    seen: set[str] = set()
    for number, line in enumerate(text.splitlines(), start=1):
        try:
            parsed = json.loads(line)
            if canonical_json(parsed) != line:
                problems.append(f"{name}:{number}: not in canonical JSON form")
            request = GenerationRequest.model_validate(parsed)
        except ValueError as exc:
            problems.append(f"{name}:{number}: invalid GenerationRequest: {str(exc)[:160]}")
            continue
        if request.request_id in seen:
            problems.append(f"{name}:{number}: duplicate request_id {request.request_id!r}")
        seen.add(request.request_id)
        requests.append(request)
    if len(requests) != entry.get("records") or entry.get("records") != len(text.splitlines()):
        problems.append(f"{name}: record count does not match the manifest {entry.get('records')}")
    if not requests:
        problems.append(f"{name}: corpus has no requests")
    return problems, requests


def load_corpus(manifest_path: str | Path) -> Corpus:
    """Load a corpus, refusing anything that does not verify."""
    problems, requests = verify_corpus(manifest_path)
    if problems:
        raise CorpusError(f"{manifest_path}: " + "; ".join(problems))
    return Corpus(Path(manifest_path), _read_manifest(Path(manifest_path)), requests)


def extract_requests(recording_path: str | Path) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Pull canonical requests out of a ``GenerationRecorder`` JSONL recording.

    Returns the requests in recording order plus what the recording says about who
    answered them (the recorded providers and outcomes), which the manifest keeps
    because replayed states were shaped by those earlier answers.
    """
    path = Path(recording_path)
    if not path.is_file():
        raise CorpusError(f"recording not found: {path}")
    requests: list[dict[str, Any]] = []
    providers: Counter[str] = Counter()
    outcomes: Counter[str] = Counter()
    for number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        if not line.strip():
            continue
        try:
            event = json.loads(line)
        except ValueError as exc:
            raise CorpusError(f"{path}:{number}: malformed JSON: {exc}") from exc
        request = event.get("request") if isinstance(event, dict) else None
        if not isinstance(request, dict):
            raise CorpusError(f"{path}:{number}: no 'request' object (not a recording event)")
        requests.append(request)
        providers[f"{event.get('provider')}/{event.get('model')}"] += 1
        outcomes[str(event.get("outcome"))] += 1
    return requests, {"recorded_providers": dict(providers), "recorded_outcomes": dict(outcomes)}


def build_corpus(
    recording_path: str | Path,
    out_dir: str | Path,
    *,
    corpus_id: str,
    kind: str,
    description: str,
    provenance: dict[str, Any] | None = None,
    expected_offline: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Write ``requests.jsonl`` and ``corpus.json`` from a recording; return the manifest."""
    if kind not in CORPUS_KINDS:
        raise CorpusError(f"kind must be one of {CORPUS_KINDS}")
    if not re.match(r"^[a-z0-9][a-z0-9._-]{0,63}$", corpus_id):
        raise CorpusError("corpus_id must be lowercase letters, digits, '.', '_' or '-'")
    raw_requests, recorded = extract_requests(recording_path)
    validated = []
    for index, raw in enumerate(raw_requests, start=1):
        try:
            validated.append(GenerationRequest.model_validate(raw))
        except ValueError as exc:
            raise CorpusError(f"request {index}: invalid GenerationRequest: {exc}") from exc
    ids = [request.request_id for request in validated]
    if len(set(ids)) != len(ids):
        raise CorpusError("recording contains duplicate request_ids")
    if not validated:
        raise CorpusError("recording contains no requests")

    lines = [canonical_json(raw) + "\n" for raw in raw_requests]
    payload = "".join(lines).encode("utf-8")
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    (out / REQUESTS_NAME).write_bytes(payload)

    per_run = Counter(request.run_id for request in validated)
    manifest: dict[str, Any] = {
        "schema_version": CORPUS_SCHEMA_VERSION,
        "corpus_id": corpus_id,
        "kind": kind,
        "description": description,
        "contract_version": CONTRACT_VERSION,
        "provenance": {**(provenance or {}), **recorded},
        "files": [
            {
                "path": REQUESTS_NAME,
                "sha256": sha256_bytes(payload),
                "bytes": len(payload),
                "records": len(lines),
            }
        ],
        "stats": {
            "runs": len(per_run),
            "requests_per_run": dict(sorted(per_run.items())),
            "depths": dict(sorted(Counter(str(r.state.depth) for r in validated).items())),
        },
    }
    if expected_offline:
        manifest["expected_offline"] = expected_offline
    (out / MANIFEST_NAME).write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return manifest
